/**
 * Receives the live events of the receiver.
 *
 * WHY: The dashboard shows a live list of sessions, the phone shows a
 * notification when a sender appears. Both need the same events, so the
 * bridge hands them out through one interface.
 */
public protocol ReceiverEventSink: AnyObject, Sendable {
    
    /**
     * Called for every event of the receiver.
     *
     * WHY: The call happens on a thread of the bridge, not on the thread
     * of the host. A host that blocks here blocks the receiver.
     */
    func onEvent(event: FfiReceiverEvent) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceReceiverEventSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceReceiverEventSink] = [UniffiVTableCallbackInterfaceReceiverEventSink(
        onEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceReceiverEventSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     event: try FfiConverterTypeFfiReceiverEvent_lift(event)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceReceiverEventSink.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface ReceiverEventSink: handle missing in uniffiFree")
            }
        }
    )]
}

private func uniffiCallbackInitReceiverEventSink() {
    uniffi_phairplay_ffi_fn_init_callback_vtable_receivereventsink(UniffiCallbackInterfaceReceiverEventSink.vtable)
}

